async function password(p){const salt=randomBytes(16).toString('hex');return salt+':'+(await derive(p,salt,64)).toString('hex')}
async function verify(p,v){const [salt,h]=v.split(':');const k=await derive(p,salt,64);return timingSafeEqual(k,Buffer.from(h,'hex'))}
const publicUser=u=>({id:u.id,username:u.username,name:u.name,bio:u.bio,created:u.created});
const clean=(v,max=200)=>typeof v==='string'?v.trim().slice(0,max):'';
const PLANS={
free:{id:'free',name:'Free',price:0,durationMonths:0,storageBytes:100*1024*1024,aiQueries:25,projects:3},
monthly:{id:'monthly',name:'Monthly',price:3,durationMonths:1,storageBytes:500*1024*1024,aiQueries:200,projects:15},
premium:{id:'premium',name:'Premium',price:10,durationMonths:3,storageBytes:2*1024*1024*1024,aiQueries:1000,projects:60},
annual:{id:'annual',name:'Full',price:80,durationMonths:12,storageBytes:10*1024*1024*1024,aiQueries:10000,projects:null}
};
const activePlan=u=>PLANS[u?.plan]&&(!u.plan_expires||u.plan_expires>Date.now())?PLANS[u.plan]:PLANS.free;
const monthKey=()=>new Date().toISOString().slice(0,7);
function usage(uid){return one('SELECT ai_queries FROM monthly_usage WHERE user_id=? AND month=?',uid,monthKey())||{ai_queries:0}}
