const planCatalog=()=>Object.values(PLANS).filter(plan=>plan.id!=='free').map(plan=>({id:plan.id,name:plan.name,price:plan.price,durationMonths:plan.durationMonths,limits:{storageBytes:plan.storageBytes,aiQueries:plan.aiQueries,projects:plan.projects}}));
const normalized=x=>String(x).toLowerCase().normalize('NFKC').replace(/[‘’ʻʼ`´]/g,"'");
const limited=new Map();function rate(key,limit=30){const t=Date.now();let a=limited.get(key)||[];a=a.filter(x=>t-x<900000);if(a.length>=limit)fail(429,'rate_limit');a.push(t);limited.set(key,a)}
const blocked=(a,b)=>!!one('SELECT 1 FROM blocks WHERE (owner=? AND target=?) OR (owner=? AND target=?)',a,b,b,a);
const areFriends=(a,b)=>!blocked(a,b)&&!!one("SELECT 1 FROM friends WHERE status='accepted' AND ((sender=? AND recipient=?) OR (sender=? AND recipient=?))",a,b,b,a);
function member(uid,rid){const r=one("SELECT m.*,r.type,r.owner,r.name,r.description FROM members m JOIN rooms r ON r.id=m.room_id WHERE m.user_id=? AND m.room_id=? AND m.status='active'",uid,rid);if(!r)fail(404,'not_found');if(r.type==='dm'){const other=one('SELECT user_id FROM members WHERE room_id=? AND user_id<>?',rid,uid);if(!other||blocked(uid,other.user_id))fail(403,'blocked')}return r}
function admin(uid,rid){const m=member(uid,rid);if(!['owner','admin'].includes(m.role))fail(403,'permission');return m}
function fileAccess(uid,fid,edit=false,trash=false){const f=one('SELECT * FROM files WHERE id=?',fid);if(!f||f.trashed&&!trash)fail(404,'not_found');if(f.owner===uid)return f;if(f.trashed||blocked(uid,f.owner))fail(404,'not_found');const grants=sql('SELECT * FROM file_grants WHERE file_id=?',fid);const ok=grants.some(g=>(!edit||g.role==='editor')&&(g.target_type==='user'&&g.target_id===uid||g.target_type==='room'&&!!one("SELECT 1 FROM members WHERE room_id=? AND user_id=? AND status='active'",g.target_id,uid)));if(!ok)fail(404,'not_found');return f}
function ownsFile(uid,fid,trash=true){const f=fileAccess(uid,fid,false,trash);if(f.owner!==uid)fail(403,'permission');return f}
function ownsProject(uid,pid){if(!pid)return null;const p=one('SELECT * FROM projects WHERE id=? AND owner=?',pid,uid);if(!p)fail(404,'not_found');return p}
function canFile(uid,fid){try{return fileAccess(uid,fid)}catch{return null}}
function fileDto(f,uid){const u=one('SELECT name,username FROM users WHERE id=?',f.owner);return {...f,content:undefined,hash:undefined,owner_name:u.name,owner_username:u.username,mine:f.owner===uid,starred:!!one('SELECT 1 FROM stars WHERE user_id=? AND file_id=?',uid,f.id),shared:one('SELECT count(*) n FROM file_grants WHERE file_id=?',f.id).n}}
function accessibleFiles(uid,trash=false){return sql('SELECT * FROM files WHERE '+(trash?'owner=? AND trashed IS NOT NULL':'trashed IS NULL')+' ORDER BY updated DESC',...(trash?[uid]:[])).filter(f=>trash||canFile(uid,f.id))}
