async function askGemini(question,sources){
if(!geminiConfigured())fail(503,'gemini_setup');
const context=sources.map((source,index)=>`[${index+1}] ${source.name}\n${source.passage}`).join('\n\n');
const prompt=`You are Memgraph's source-grounded memory assistant. Answer only from the supplied sources. If the sources are insufficient or conflict, say so clearly. Never invent facts. Keep the answer concise, use the same language as the question, and cite claims with source numbers like [1].\n\nQUESTION:\n${question}\n\nSOURCES:\n${context}`;
const endpoint=`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(geminiModel())}:generateContent`;
const result=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json','x-goog-api-key':process.env.GEMINI_API_KEY},body:JSON.stringify({contents:[{role:'user',parts:[{text:prompt}]}],generationConfig:{temperature:0.2,maxOutputTokens:1200}})});
if(!result.ok){console.error('Gemini request failed:',result.status,await result.text());fail(502,'gemini_error')}
const data=await result.json();
const answer=data.candidates?.[0]?.content?.parts?.map(part=>part.text||'').join('').trim();
if(!answer)fail(502,'gemini_error');
return answer;
}
